function data(rg,mode){const n=rg=="week"?7:rg=="month"?30:12;const lb=rg=="week"?["Sun 4","Mon 5","Tue 6","Wed 7","Thu 8","Fri 9","Sat 10"]:rg=="month"?[...Array(30)].map((_,i)=>i+1):["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
const k=rg=="week"?1:rg=="month"?3:20,f=(a,b)=>[...Array(n)].map((_,i)=>Math.round((a+Math.sin(i*b)*a*.4+i*a*.05)*k));return{lb,a:f(6,.9),b:f(25,.6),c:f(18,.4)}}
function chart(id,names,rg,type){const d=zd(id,data(rg)),sets=[{label:names[0],data:d.a,backgroundColor:"#f59e0b",borderColor:"#f59e0b",type:type=="line"?"line":"bar",order:3},{label:names[1],data:d.b,borderColor:"#93c5fd",backgroundColor:"rgba(147,197,253,.25)",type:type=="bar"?"bar":"line",fill:true,tension:.4,order:2},{label:names[2],data:d.c,borderColor:"#86efac",type:type=="bar"?"bar":"line",borderDash:[6,4],tension:.4,order:1,backgroundColor:"#86efac"}];
if(type=="line")sets[0].backgroundColor="#f59e0b";if(ch[id])ch[id].destroy();
ch[id]=new Chart($(id),{data:{labels:d.lb,datasets:sets},options:{responsive:true,maintainAspectRatio:false,interaction:{mode:"index",intersect:false},plugins:{legend:{labels:{color:"#fff"}}},scales:{x:{ticks:{color:"#c6d6ff"},grid:{display:false}},y:{ticks:{color:"#c6d6ff"},grid:{color:"rgba(255,255,255,.12)"}}}}});
const a=d.a,mx=a.indexOf(Math.max(...a)),mn=a.indexOf(Math.min(...a)),av=Math.round(a.reduce((x,y)=>x+y,0)/a.length),h=Math.floor(a.length/2),s1=a.slice(0,h).reduce((x,y)=>x+y,0),s2=a.slice(h).reduce((x,y)=>x+y,0),tr=s1?Math.round((s2-s1)/s1*100):0;
$(id+"i").innerHTML=`<div>Best<b>${d.lb[mx]} · ${a[mx]}</b></div><div>Lowest<b>${d.lb[mn]} · ${a[mn]}</b></div><div>Average<b>${av}</b></div><div>Trend<b class="${tr>=0?"up":"dn"}">${tr>=0?"▲":"▼"} ${Math.abs(tr)}%</b></div>`}
