function cact(ph){const a=accts.find(x=>x.ph==ph);a.off=a.off?0:1;jobs.forEach(j=>{if(j.c==(a.cn||a.n)){if(a.off&&j.st=="Active")j.st="Inactive";else if(!a.off&&j.st=="Inactive")j.st="Active"}});notify(a.ph,a.off?"Your company was set to Inactive":"Your company is Active again",[a.off?"Your jobs are hidden from candidates.":"Your jobs are visible to candidates again."]);render(1)}
