if(V=="login")return `<div class="gl">${lgc}<h2>Log in</h2><label style="margin-top:0">Contact number</label><div class="seg2"><button class="${A.m=="mobile"?"on":""}" onclick="A.m='mobile';render()">📱 Mobile number</button><button class="${A.m=="email"?"on":""}" onclick="A.m='email';render()">✉️ Email</button></div>${A.m=="mobile"?f("lid","","98765 43210","tel","","+91 ⌄").replace("<label></label>",'<div style="height:10px"></div>')+'<div class="hint">Enter your 10-digit mobile number</div>':f("lid","","name@example.com","email").replace("<label></label>",'<div style="height:10px"></div>')+'<div class="hint">Enter your registered email address</div>'}${f("lpw","Password","","password")}<div class="row" style="border:0"><label style="margin:0"><input id="rm" type="checkbox" checked style="width:auto"> Remember me</label>${lnk("forgot","Forgot password?")}</div><button class="btn big" onclick="login()">Log in</button><p class="sub" style="font-weight:700">New user? ${lnk("reg","Register")}</p><div class="hint" style="text-align:center">Sign in with your registered account.<br><a href="#" style="color:var(--mut)" onclick="resetAll();return false">Reset local app data</a></div></div>`;
