if(A.st==1)return `<h2 style="text-align:center;font-size:36px;margin:20px 0 4px">Welcome to JobConnect Bijapur</h2><p class="sub" style="text-align:center">Choose your role and create your account to access tailored services.</p><div class="rg">${Object.entries(rl).filter(([k])=>k!="adm").map(([k,v])=>`<div class="rc" style="background:${v[3]};--ac:${v[4]}"><div class="ic">${v[2]}</div><h3>${v[0]}</h3><p>${v[1]}</p><ul>${v[5].map(x=>`<li>${x}</li>`).join("")}</ul><button class="btn" onclick="A.rr='${k}';A.st=2;render()">Register as ${v[0]} →</button></div>`).join("")}</div><p class="sub" style="text-align:center">Government Admin accounts are created by the platform owner.</p><div class="trust"><span>🛡️ Safe & Secure</span><span>👥 Trusted Platform</span><span>⚙️ Government Verified</span><span>📈 Building a Better Tomorrow</span></div><p class="sub" style="text-align:center">Already have an account? ${lnk("login","Log in")}</p>`;
const r=A.rr,T=rl[r][0];
