if(r=="cand")form+=`<div class="sec">Education Details</div><div class="g2f"><div>${sel("rq","Highest Qualification *",["10th","12th","Diploma","B.A / B.Com / B.Sc","B.E / B.Tech","Master's"])}</div><div>${f("rs","Education Stream / Course *","e.g. B.Tech, B.Com")}</div><div>${f("ry","Year of Passing *","YYYY","number")}</div></div><div class="sec">Skills & Experience</div><div class="g2f"><div>${f("rk","Skills (at least 3, comma separated) *","Python, Java, Communication")}</div><div>${sel("rx","Work Experience",["Fresher","1-2 years","3-5 years","5+ years"])}</div></div><div class="sec">Upload Documents</div><div class="g2f"><div><label>Resume (PDF, max 2MB) *</label><input id="rf" type="file" accept=".pdf"></div><div><label>Profile Photo (JPG/PNG, max 2MB) *</label><input id="rpf" type="file" accept="image/png,image/jpeg"></div></div>`;
